INSERT INTO bncc_objetivos (tipo_ensino, etapa, faixa_etaria, campo_experiencia, codigo_bncc, descricao) VALUES
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Corpo, Gestos e Movimento', 'EI02CG01', 'Apropriar-se de gestos e movimentos de sua cultura no cuidado de si e nos jogos e brincadeiras.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Corpo, Gestos e Movimento', 'EI02CG02', 'Deslocar seu corpo no espaço, orientando-se por noções como em frente, atrás, no alto, embaixo, dentro, fora etc.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Corpo, Gestos e Movimento', 'EI02CG03', 'Explorar formas de deslocamento no espaço (pular, saltar, dançar), combinando movimentos e seguindo orientações.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Corpo, Gestos e Movimento', 'EI02CG04', 'Demonstrar progressiva independência no cuidado do seu corpo.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Corpo, Gestos e Movimento', 'EI02CG05', 'Desenvolver progressivamente as habilidades manuais, adquirindo controle para desenhar, pintar, rasgar, folhear.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI02EF01', 'Dialogar com crianças e adultos, expressando seus desejos, necessidades, sentimentos e opiniões.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI02EF02', 'Identificar e criar diferentes sons e reconhecer rimas e aliterações em cantigas de roda e textos poéticos.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI02EF03', 'Demonstrar interesse e atenção ao ouvir a leitura de histórias e outros textos.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI02EF04', 'Formular e responder perguntas sobre fatos da história narrada.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI02EF05', 'Relatar experiências e fatos acontecidos, histórias ouvidas, filmes ou peças teatrais assistidos.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI02EF06', 'Criar e contar histórias oralmente, com base em imagens ou temas sugeridos.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI02EF07', 'Manusear diferentes portadores textuais, demonstrando reconhecer seus usos sociais.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI02EF08', 'Manipular textos e participar de situações de escuta para ampliar seu contato com diferentes gêneros textuais.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI02EF09', 'Manusear diferentes instrumentos e suportes de escrita para desenhar, traçar letras e outros sinais gráficos.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Espaços, tempos, quantidades, relações e transformações', 'EI02ET01', 'Explorar e descrever semelhanças e diferenças entre as características e propriedades dos objetos.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Espaços, tempos, quantidades, relações e transformações', 'EI02ET02', 'Observar, relatar e descrever incidentes do cotidiano e fenômenos naturais.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Espaços, tempos, quantidades, relações e transformações', 'EI02ET03', 'Compartilhar, com outras crianças, situações de cuidado de plantas e animais.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Espaços, tempos, quantidades, relações e transformações', 'EI02ET04', 'Identificar relações espaciais (dentro e fora, em cima, embaixo, acima, abaixo, entre e do lado) e temporais.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Espaços, tempos, quantidades, relações e transformações', 'EI02ET05', 'Classificar objetos, considerando determinado atributo.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Espaços, tempos, quantidades, relações e transformações', 'EI02ET06', 'Utilizar conceitos básicos de tempo (agora, antes, durante, depois, ontem, hoje, amanhã).'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Espaços, tempos, quantidades, relações e transformações', 'EI02ET07', 'Contar oralmente objetos, pessoas, livros etc., em contextos diversos.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Espaços, tempos, quantidades, relações e transformações', 'EI02ET08', 'Registrar com números a quantidade de crianças e a quantidade de objetos.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'O eu, o outro e o nós', 'EI02EO01', 'Demonstrar atitudes de cuidado e solidariedade na interação com crianças e adultos.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'O eu, o outro e o nós', 'EI02EO02', 'Demonstrar imagem positiva de si e confiança em sua capacidade para enfrentar dificuldades.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'O eu, o outro e o nós', 'EI02EO03', 'Compartilhar os objetos e os espaços com crianças da mesma faixa etária e adultos.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'O eu, o outro e o nós', 'EI02EO04', 'Comunicar-se com os colegas e os adultos, buscando compreendê-los e fazendo-se compreender.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'O eu, o outro e o nós', 'EI02EO05', 'Perceber que as pessoas têm características físicas diferentes, respeitando essas diferenças.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'O eu, o outro e o nós', 'EI02EO06', 'Respeitar regras básicas de convívio social nas interações e brincadeiras.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'O eu, o outro e o nós', 'EI02EO07', 'Resolver conflitos nas interações e brincadeiras, com a orientação de um adulto.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Traços, Sons, Cores e Formas', 'EI02TS01', 'Criar sons com materiais, objetos e instrumentos musicais, para acompanhar diversos ritmos.'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Traços, Sons, Cores e Formas', 'EI02TS02', 'Utilizar materiais variados com possibilidades de manipulação (argila, massa de modelar).'),
('infantil', 'creche', 'Crianças bem pequenas (1 ano e 7 meses a 3 anos e 11 meses)', 'Traços, Sons, Cores e Formas', 'EI02TS03', 'Utilizar diferentes fontes sonoras disponíveis no ambiente em brincadeiras cantadas.');
INSERT INTO bncc_objetivos (tipo_ensino, etapa, faixa_etaria, campo_experiencia, codigo_bncc, descricao) VALUES
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Corpo, Gestos e Movimento', 'EI03CG01', 'Criar com o corpo formas diversificadas de expressão de sentimentos, sensações e emoções.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Corpo, Gestos e Movimento', 'EI03CG02', 'Demonstrar controle e adequação do uso de seu corpo em brincadeiras e jogos.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Corpo, Gestos e Movimento', 'EI03CG03', 'Criar movimentos, gestos, olhares e mímicas em brincadeiras, jogos e atividades artísticas.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Corpo, Gestos e Movimento', 'EI03CG04', 'Adotar hábitos de autocuidado relacionados a higiene, alimentação, conforto e aparência.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Corpo, Gestos e Movimento', 'EI03CG05', 'Coordenar suas habilidades manuais no atendimento adequado a seus interesses e necessidades.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI03EF01', 'Expressar ideias, desejos e sentimentos sobre suas vivências, por meio da linguagem oral e escrita.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI03EF02', 'Inventar brincadeiras cantadas, poemas e canções, criando rimas, aliterações e ritmos.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI03EF03', 'Escolher e folhear livros, procurando orientar-se por temas e ilustrações.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI03EF04', 'Recontar histórias ouvidas e planejar coletivamente roteiros de vídeos e de encenações.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI03EF05', 'Recontar histórias ouvidas para produção de reconto escrito, tendo o professor como escriba.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI03EF06', 'Produzir suas próprias histórias orais e escritas (escrita espontânea).'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI03EF07', 'Levantar hipóteses sobre gêneros textuais veiculados em portadores conhecidos.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI03EF08', 'Selecionar livros e textos de gêneros conhecidos para a leitura.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Escuta, Fala, Pensamento e Imaginação', 'EI03EF09', 'Levantar hipóteses em relação à linguagem escrita, realizando registros de palavras e textos.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Espaços, tempos, quantidades, relações e transformações', 'EI03ET01', 'Estabelecer relações de comparação entre objetos, observando suas propriedades.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Espaços, tempos, quantidades, relações e transformações', 'EI03ET02', 'Observar e descrever mudanças em diferentes materiais, resultantes de ações sobre eles.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Espaços, tempos, quantidades, relações e transformações', 'EI03ET03', 'Identificar e selecionar fontes de informações, para responder a questões sobre a natureza.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Espaços, tempos, quantidades, relações e transformações', 'EI03ET04', 'Registrar observações, manipulações e medidas, usando múltiplas linguagens.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Espaços, tempos, quantidades, relações e transformações', 'EI03ET05', 'Classificar objetos e figuras de acordo com suas semelhanças e diferenças.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Espaços, tempos, quantidades, relações e transformações', 'EI03ET06', 'Relatar fatos importantes sobre seu nascimento e desenvolvimento, a história dos seus familiares.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Espaços, tempos, quantidades, relações e transformações', 'EI03ET07', 'Relacionar números às suas respectivas quantidades e identificar o antes, o depois e o entre.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Espaços, tempos, quantidades, relações e transformações', 'EI03ET08', 'Exprimir medidas (peso, altura etc.), construindo gráficos básicos.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'O eu, o outro e o nós', 'EI03EO01', 'Demonstrar empatia pelos outros, percebendo que as pessoas têm diferentes sentimentos.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'O eu, o outro e o nós', 'EI03EO02', 'Agir de maneira independente, com confiança em suas capacidades.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'O eu, o outro e o nós', 'EI03EO03', 'Ampliar as relações interpessoais, desenvolvendo atitudes de participação e cooperação.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'O eu, o outro e o nós', 'EI03EO04', 'Comunicar suas ideias e sentimentos a pessoas e grupos diversos.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'O eu, o outro e o nós', 'EI03EO05', 'Demonstrar valorização das características de seu corpo e respeitar as características dos outros.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'O eu, o outro e o nós', 'EI03EO06', 'Manifestar interesse e respeito por diferentes culturas e modos de vida.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'O eu, o outro e o nós', 'EI03EO07', 'Usar estratégias pautadas no respeito mútuo para lidar com conflitos.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Traços, Sons, Cores e Formas', 'EI03TS01', 'Utilizar sons produzidos por materiais, objetos e instrumentos musicais durante brincadeiras.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Traços, Sons, Cores e Formas', 'EI03TS02', 'Expressar-se livremente por meio de desenho, pintura, colagem, dobradura e escultura.'),
('infantil', 'pre-escola', 'Crianças pequenas (4 anos a 5 anos e 11 meses)', 'Traços, Sons, Cores e Formas', 'EI03TS03', 'Reconhecer as qualidades do som (intensidade, duração, altura e timbre).');
